SELECT A.ENTRUST_ID entrustId, A.TRADER trader, A.TRADING_HEADER tradingHeader, A.CREATE_USER createUser, A.CREATE_DEPT createDept, A.CREATE_TIME createTime, A.UPDATE_USER updateUser, A.UPDATE_TIME updateTime FROM ETR_DISTRIBUTE_INTERF_TMP A
1=1
AND A.Entrust_Id = #{entrustId}

SELECT COUNT(1) FROM ( SELECT ENTRUST_ID FROM WFL_REG_FIN_PRODUCT_DEAL
ENTRUST_ID in
#{item}
UNION ALL SELECT ENTRUST_ID FROM WFL_IBU_QUOTE_ETR_RE
ENTRUST_ID in
#{item}
UNION ALL SELECT T2.ENTRUST_ID FROM REG_FIN_PRODUCT_DEAL_TOTAL T1 INNER JOIN REG_FIN_PRODUCT_DEAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID
and T2.ENTRUST_ID in
#{item}
WHERE T1.TRADE_STATUS = '01' AND (T1.IS_CANCEL IS NULL OR T1.IS_CANCEL = 'N') and NOT EXISTS ( SELECT 1 FROM TRDQUTO_MATCH_INFO T3 WHERE T3.PRE_TRADE_ID = T1.TOTLE_TRADE_ID) UNION ALL SELECT T2.ENTRUST_ID FROM IBU_QUOTE_BOND T1 INNER JOIN IBU_QUOTE_ETR_RE T2 ON T1.QUOTE_ID = T2.QUOTE_ID
and T2.ENTRUST_ID in
#{item}
WHERE T1.TRADE_STATUS = '01' and NOT EXISTS ( SELECT 1 FROM TRDQUTO_MATCH_INFO T3 WHERE T3.PRE_TRADE_ID = T1.QUOTE_ID))

SELECT EXERCISE_DATE , ACT_EXERCISE_DATE FROM FIN_EXERCISE_PLAN T1 WHERE FINPROD_ID = #{finprodId}
AND EXERCISE_TYPE = #{exerciseType}
AND EXISTS ( SELECT 1 FROM ( SELECT MIN(EXERCISE_DATE)EXERCISE_DATE, FINPROD_ID FROM FIN_EXERCISE_PLAN WHERE EXERCISE_DATE >= to_date(#{platDate}, 'yyyy-MM-dd') GROUP BY FINPROD_ID) T2 WHERE T2.EXERCISE_DATE = T1.EXERCISE_DATE AND T2.FINPROD_ID = T1.FINPROD_ID )

SELECT COUNT(1) FROM  ETR_ENTRUST WHERE ENTRUST_STATUS != #{entrustStatus}

    and ENTRUST_ID in

        #{item}
